1	/**
2	 * Objective Independent Review Boundary (Nexus Code v1.1.2)
3	 *
4	 * Mitigates common-mode failure and confirmation bias in multi-agent workflows.
5	 * The independent reviewer receives an objective evidence package containing:
6	 * - Original task requirements and acceptance criteria
7	 * - Authorized scope (files permitted to be modified)
8	 * - Repository baseline and candidate diff
9	 * - Deterministic verifier receipts (exit code, raw logs)
10	 *
11	 * CRITICAL INVARIANT: The implementer's narrative ("I fixed this and verified it works")
12	 * is strictly stripped from the evidence package to prevent confirmation bias.
13	 *
14	 * Internal model metrics may veto an implementation, but deterministic verification
15	 * gates remain the authoritative ground truth for completion.
16	 */
17	
18	export interface ReviewEvidencePackage {
19	  operationId: string;
20	  unitId: string;
21	  objective: string;
22	  authorizedScope: readonly string[];
23	  baselineCommit: string;
24	  candidateCommit?: string;
25	  unifiedDiff: string;
26	  verifierCommand?: string;
27	  verifierOutput?: string;
28	  verifierExitCode?: number;
29	  unresolvedAssumptions?: readonly string[];
30	}
31	
32	export interface ReviewDefect {
33	  path: string;
34	  line?: number;
35	  description: string;
36	}
37	
38	export interface IndependentReviewVerdict {
39	  verdict: "ACCEPT" | "REJECT";
40	  verifiedObservations: string[];
41	  suspectedDefects: ReviewDefect[];
42	  unprovenCriteria: string[];
43	  scopeViolations: string[];
44	  reviewerConfidenceNote: string;
45	}
46	
47	/**
48	 * Parses files modified from a unified git diff.
49	 */
50	export function extractModifiedFilesFromDiff(diff: string): string[] {
51	  const modified = new Set<string>();
52	  const lines = diff.split("\n");
53	  for (const line of lines) {
54	    if (line.startsWith("diff --git a/")) {
55	      const parts = line.split(" ");
56	      if (parts.length >= 4) {
57	        const fileB = parts[3].replace(/^b\//, "");
58	        if (fileB && fileB !== "/dev/null") {
59	          modified.add(fileB);
60	        }
61	      }
62	    } else if (line.startsWith("+++ b/")) {
63	      const file = line.replace(/^\+\+\+ b\//, "").trim();
64	      if (file && file !== "/dev/null") {
65	        modified.add(file);
66	      }
67	    }
68	  }
69	  return Array.from(modified);
70	}
71	
72	/**
73	 * Checks whether any modified file is outside the authorized change boundary.
74	 */
75	export function detectScopeViolations(
76	  diff: string,
77	  authorizedScope: readonly string[],
78	): string[] {
79	  if (authorizedScope.length === 0) return [];
80	  const modifiedFiles = extractModifiedFilesFromDiff(diff);
81	  const violations: string[] = [];
82	
83	  for (const file of modifiedFiles) {
84	    const isAuthorized = authorizedScope.some(
85	      (auth) => file === auth || file.startsWith(`${auth}/`) || auth === "*",
86	    );
87	    if (!isAuthorized) {
88	      violations.push(file);
89	    }
90	  }
91	  return violations;
92	}
93	
94	/**
95	 * Builds an objective evidence package. Strips any author-supplied narrative summaries.
96	 */
97	export function buildReviewEvidencePackage(params: {
98	  operationId: string;
99	  unitId: string;
100	  objective: string;
101	  authorizedScope: readonly string[];
102	  baselineCommit: string;
103	  candidateCommit?: string;
104	  unifiedDiff: string;
105	  verifierCommand?: string;
106	  verifierOutput?: string;
107	  verifierExitCode?: number;
108	  unresolvedAssumptions?: readonly string[];
109	}): ReviewEvidencePackage {
110	  return {
111	    operationId: params.operationId,
112	    unitId: params.unitId,
113	    objective: params.objective.trim(),
114	    authorizedScope: Object.freeze([...params.authorizedScope]),
115	    baselineCommit: params.baselineCommit.trim(),
116	    candidateCommit: params.candidateCommit?.trim(),
117	    unifiedDiff: params.unifiedDiff,
118	    verifierCommand: params.verifierCommand?.trim(),
119	    verifierOutput: params.verifierOutput,
120	    verifierExitCode: params.verifierExitCode,
121	    unresolvedAssumptions: params.unresolvedAssumptions
122	      ? Object.freeze([...params.unresolvedAssumptions])
123	      : undefined,
124	  };
125	}
126	
127	/**
128	 * Formats the review prompt, instructing the independent model to evaluate
129	 * only the objective evidence package and emit a strict JSON verdict.
130	 */
131	export function formatIndependentReviewPrompt(
132	  pkg: ReviewEvidencePackage,
133	): string {
134	  const scopeViolations = detectScopeViolations(pkg.unifiedDiff, pkg.authorizedScope);
135	  const scopeWarning = scopeViolations.length
136	    ? `\n[AUTOMATED SCOPE WARNING] The diff touches files outside authorizedScope: [${scopeViolations.join(", ")}]\n`
137	    : "";
138	
139	  return `[Independent Review Task for Unit '${pkg.unitId}' in Operation '${pkg.operationId}']
140	
141	Objective Requirements:
142	${pkg.objective}
143	
144	Authorized Scope:
145	${pkg.authorizedScope.length ? pkg.authorizedScope.map((s) => `- ${s}`).join("\n") : "Unrestricted (Repository-wide)"}
146	${scopeWarning}
147	Repository Baseline:
148	- Base Commit: ${pkg.baselineCommit}${pkg.candidateCommit ? `\n- Candidate Commit: ${pkg.candidateCommit}` : ""}
149	
150	Verifier Execution Evidence:
151	- Command: ${pkg.verifierCommand ?? "None"}
152	- Exit Code: ${pkg.verifierExitCode !== undefined ? pkg.verifierExitCode : "Untested"}
153	- Raw Verifier Output:
154	\`\`\`
155	${(pkg.verifierOutput ?? "No verifier output recorded").slice(0, 10000)}
156	\`\`\`
157	
158	Candidate Unified Diff:
159	\`\`\`diff
160	${pkg.unifiedDiff.slice(0, 20000)}
161	\`\`\`
162	
163	INSTRUCTIONS FOR INDEPENDENT REVIEWER:
164	1. Do not assume the implementation is correct. The implementer's self-assessed narrative has been excluded.
165	2. Evaluate the code diff against the objective requirements and authorized scope.
166	3. Check for regressions, unhandled edge cases, security boundaries, and incomplete logic.
167	4. You MUST respond with a JSON block adhering strictly to this schema:
168	\`\`\`json
169	{
170	  "verdict": "ACCEPT" | "REJECT",
171	  "verifiedObservations": ["string"],
172	  "suspectedDefects": [{"path": "string", "line": 0, "description": "string"}],
173	  "unprovenCriteria": ["string"],
174	  "scopeViolations": ["string"],
175	  "reviewerConfidenceNote": "string"
176	}
177	\`\`\`
178	`;
179	}
180	
181	/**
182	 * Parses and validates an independent reviewer verdict.
183	 * Fails closed as "REJECT" if parsing fails or critical schema invariants are violated.
184	 */
185	export function parseIndependentReviewVerdict(
186	  rawText: string,
187	  pkg?: ReviewEvidencePackage,
188	): IndependentReviewVerdict {
189	  try {
190	    const jsonMatch = rawText.match(/```(?:json)?\s*([\s\S]*?)\s*```/) || [null, rawText];
191	    const candidate = jsonMatch[1] ? jsonMatch[1].trim() : rawText.trim();
192	    const parsed = JSON.parse(candidate);
193	
194	    if (!parsed || typeof parsed !== "object") {
195	      throw new Error("Verdict is not a JSON object");
196	    }
197	
198	    const verdict: "ACCEPT" | "REJECT" = parsed.verdict === "ACCEPT" ? "ACCEPT" : "REJECT";
199	    const verifiedObservations = Array.isArray(parsed.verifiedObservations)
200	      ? parsed.verifiedObservations.map(String)
201	      : [];
202	    const unprovenCriteria = Array.isArray(parsed.unprovenCriteria)
203	      ? parsed.unprovenCriteria.map(String)
204	      : [];
205	    const scopeViolations = Array.isArray(parsed.scopeViolations)
206	      ? parsed.scopeViolations.map(String)
207	      : [];
208	
209	    const suspectedDefects: ReviewDefect[] = [];
210	    if (Array.isArray(parsed.suspectedDefects)) {
211	      for (const d of parsed.suspectedDefects) {
212	        if (d && typeof d === "object" && typeof d.path === "string" && typeof d.description === "string") {
213	          suspectedDefects.push({
214	            path: d.path,
215	            line: typeof d.line === "number" ? d.line : undefined,
216	            description: d.description,
217	          });
218	        }
219	      }
220	    }
221	
222	    // Deterministic gate enforcement: If verifier explicitly failed (exitCode !== 0)
223	    // or deterministic scope violations exist, model ACCEPT cannot override objective failure.
224	    let finalVerdict = verdict;
225	    if (pkg) {
226	      const autoViolations = detectScopeViolations(pkg.unifiedDiff, pkg.authorizedScope);
227	      for (const v of autoViolations) {
228	        if (!scopeViolations.includes(v)) scopeViolations.push(v);
229	      }
230	      if (pkg.verifierExitCode !== undefined && pkg.verifierExitCode !== 0) {
231	        finalVerdict = "REJECT";
232	        unprovenCriteria.push(`Deterministic verifier failed with exit code ${pkg.verifierExitCode}`);
233	      }
234	      if (scopeViolations.length > 0) {
235	        finalVerdict = "REJECT";
236	      }
237	    }
238	
239	    if (suspectedDefects.length > 0) {
240	      finalVerdict = "REJECT";
241	    }
242	
243	    return {
244	      verdict: finalVerdict,
245	      verifiedObservations,
246	      suspectedDefects,
247	      unprovenCriteria,
248	      scopeViolations,
249	      reviewerConfidenceNote: typeof parsed.reviewerConfidenceNote === "string"
250	        ? parsed.reviewerConfidenceNote
251	        : "Automated parsed verdict",
252	    };
253	  } catch (err) {
254	    // Fail-closed as REJECT on any parse failure
255	    return {
256	      verdict: "REJECT",
257	      verifiedObservations: [],
258	      suspectedDefects: [
259	        {
260	          path: "review_verdict.json",
261	          description: `Failed to parse structured review verdict: ${err instanceof Error ? err.message : String(err)}`,
262	        },
263	      ],
264	      unprovenCriteria: ["Structured review verdict validation"],
265	      scopeViolations: [],
266	      reviewerConfidenceNote: "Parser failure: default fail-closed REJECT",
267	    };
268	  }
269	}
