147	export class ToolAccessDeniedError extends Error {
148	  constructor(
149	    readonly role: SpecialistRole,
150	    readonly toolName: string,
151	    readonly permittedTools: readonly string[],
152	  ) {
153	    super(
154	      `Specialist role '${role}' is not permitted to execute tool '${toolName}'. Permitted tools: [${permittedTools.join(", ")}].`,
155	    );
156	    this.name = "ToolAccessDeniedError";
157	  }
158	}
159	
160	/**
161	 * Validates whether a specialist profile is authorized to call a specific tool.
162	 * Throws ToolAccessDeniedError if the tool is not whitelisted.
163	 */
164	export function validateSpecialistToolAccess(role: SpecialistRole, toolName: string): void {
165	  const contract = SPECIALIST_CONTRACTS[role];
166	  if (!contract) {
167	    throw new Error(`Unknown specialist role: '${role}'`);
168	  }
169	  if (!contract.permittedTools.includes(toolName)) {
170	    throw new ToolAccessDeniedError(role, toolName, contract.permittedTools);
171	  }
172	}
173	
174	export function isSpecialistRole(role: string | undefined): role is SpecialistRole {
175	  return role !== undefined && role in SPECIALIST_CONTRACTS;
176	}
177	
178	export interface SpecialistEvidenceItem {
179	  path: string;
180	  lineRange?: [number, number];
181	  note: string;
182	}
183	
184	export interface SpecialistStructuredOutput<T = unknown> {
185	  specialistRole: SpecialistRole;
186	  status: "SUCCESS" | "FAILED" | "INCONCLUSIVE";
187	  summary: string;
188	  findings: T;
189	  evidence: SpecialistEvidenceItem[];
190	  escalationRecommended: boolean;
191	  escalationReason?: string;
192	}
193	
194	export function validateSpecialistOutput<T>(
195	  role: SpecialistRole,
196	  raw: unknown,
197	): SpecialistStructuredOutput<T> {
198	  if (!raw || typeof raw !== "object") {
199	    throw new Error(`Specialist output must be an object, received: ${typeof raw}`);
200	  }
201	  const obj = raw as Record<string, unknown>;
202	  if (obj.specialistRole !== role) {
203	    throw new Error(`Specialist output role mismatch: expected '${role}', got '${obj.specialistRole}'`);
204	  }
205	  if (!["SUCCESS", "FAILED", "INCONCLUSIVE"].includes(obj.status as string)) {
206	    throw new Error(`Invalid specialist status: '${obj.status}'`);
207	  }
208	  if (typeof obj.summary !== "string" || obj.summary.trim().length === 0) {
209	    throw new Error("Specialist output must include a non-empty summary string");
210	  }
211	  if (!Array.isArray(obj.evidence)) {
212	    throw new Error("Specialist output must include an evidence array");
213	  }
214	  for (const item of obj.evidence) {
215	    if (!item || typeof item !== "object" || typeof item.path !== "string") {
216	      throw new Error("Each evidence item must contain a 'path' string");
217	    }
218	  }
219	  return obj as unknown as SpecialistStructuredOutput<T>;
220	}
