/**
 * Bounded Specialist Agent Contracts & Profiles (Nexus Code v1.1.2)
 *
 * Defines explicit contracts for specialized subagent workflows:
 * - Permitted tool whitelist
 * - Read-only enforcement
 * - Input requirements and evidence prerequisites
 * - Structured output schema validation
 * - Token budget ceilings and escalation thresholds
 *
 * Deterministic operations (ordinary file discovery, grep, AST queries, git diff)
 * remain deterministic tools. Specialists provide bounded semantic analysis.
 */

export type SpecialistRole =
  | "semantic_explorer"
  | "call_site_analyzer"
  | "failure_debugger"
  | "security_reviewer"
  | "acceptance_reviewer";

export interface SpecialistContract {
  role: SpecialistRole;
  title: string;
  description: string;
  permittedTools: readonly string[];
  readOnly: boolean;
  maxContextTokens: number;
  inputRequirements: readonly string[];
  outputSchemaName: string;
  escalationCriteria: string[];
}

export const SPECIALIST_CONTRACTS: Record<SpecialistRole, SpecialistContract> = {
  semantic_explorer: {
    role: "semantic_explorer",
    title: "Codebase Semantic Explorer",
    description: "Performs targeted conceptual discovery, cross-file pattern analysis, and architectural mapping.",
    permittedTools: [
      "read_file",
      "batch_read",
      "search_code",
      "search_symbols",
      "find_files",
      "file_info",
      "file_tree",
      "task_completed",
    ],
    readOnly: true,
    maxContextTokens: 16000,
    inputRequirements: ["target_query", "focus_directories"],
    outputSchemaName: "SemanticExplorationOutput",
    escalationCriteria: [
      "Query matches 0 relevant code symbols after exhaustive search",
      "Conflicting architectural patterns detected across modules",
    ],
  },

  call_site_analyzer: {
    role: "call_site_analyzer",
    title: "Dependency & Call-Site Analyzer",
    description: "Traces call graphs, parameter flows, type contracts, and cross-package dependency impacts.",
    permittedTools: [
      "read_file",
      "batch_read",
      "search_code",
      "search_symbols",
      "file_info",
      "task_completed",
    ],
    readOnly: true,
    maxContextTokens: 24000,
    inputRequirements: ["symbol_name", "defining_path"],
    outputSchemaName: "CallSiteAnalysisOutput",
    escalationCriteria: [
      "Dynamic reflection or untyped call-sites prevent static dependency resolution",
      "Public API boundary change affects external consumers",
    ],
  },

  failure_debugger: {
    role: "failure_debugger",
    title: "Failure Investigation & Root-Cause Debugger",
    description: "Analyzes stack traces, compiler errors, test logs, and isolates root-cause failure points.",
    permittedTools: [
      "read_file",
      "batch_read",
      "search_code",
      "run_command",
      "run_tests",
      "file_info",
      "task_completed",
    ],
    readOnly: true,
    maxContextTokens: 32000,
    inputRequirements: ["failure_log", "reproduction_command"],
    outputSchemaName: "FailureDebugOutput",
    escalationCriteria: [
      "Failure cannot be reproduced deterministically in isolated environment",
      "Failure is caused by unmodeled host platform dependency or environmental drift",
    ],
  },

  security_reviewer: {
    role: "security_reviewer",
    title: "Security & Vulnerability Reviewer",
    description: "Audits diffs for injection vectors, path traversal, credential exposure, and unsafe execution.",
    permittedTools: [
      "read_file",
      "batch_read",
      "search_code",
      "file_info",
      "task_completed",
    ],
    readOnly: true,
    maxContextTokens: 24000,
    inputRequirements: ["unified_diff", "authorized_scope"],
    outputSchemaName: "SecurityReviewOutput",
    escalationCriteria: [
      "Diff touches sensitive credential stores, crypto roots, or shell sanitization routines",
      "Ambiguous input validation boundary requires architect review",
    ],
  },

  acceptance_reviewer: {
    role: "acceptance_reviewer",
    title: "Independent Acceptance Reviewer",
    description: "Conducts independent, un-biased verification against raw requirements and objective test evidence.",
    permittedTools: [
      "read_file",
      "batch_read",
      "search_code",
      "file_info",
      "task_completed",
    ],
    readOnly: true,
    maxContextTokens: 32000,
    inputRequirements: ["raw_requirements", "authorized_scope", "unified_diff", "verifier_evidence"],
    outputSchemaName: "IndependentReviewVerdict",
    escalationCriteria: [
      "Acceptance criteria lack unambiguous deterministic test proofs",
      "Candidate diff touches files outside authorized change boundary",
    ],
  },
};

export class ToolAccessDeniedError extends Error {
  constructor(
    readonly role: SpecialistRole,
    readonly toolName: string,
    readonly permittedTools: readonly string[],
  ) {
    super(
      `Specialist role '${role}' is not permitted to execute tool '${toolName}'. Permitted tools: [${permittedTools.join(", ")}].`,
    );
    this.name = "ToolAccessDeniedError";
  }
}

/**
 * Validates whether a specialist profile is authorized to call a specific tool.
 * Throws ToolAccessDeniedError if the tool is not whitelisted.
 */
export function validateSpecialistToolAccess(role: SpecialistRole, toolName: string): void {
  const contract = SPECIALIST_CONTRACTS[role];
  if (!contract) {
    throw new Error(`Unknown specialist role: '${role}'`);
  }
  if (!contract.permittedTools.includes(toolName)) {
    throw new ToolAccessDeniedError(role, toolName, contract.permittedTools);
  }
}

export function isSpecialistRole(role: string | undefined): role is SpecialistRole {
  return role !== undefined && role in SPECIALIST_CONTRACTS;
}

export interface SpecialistEvidenceItem {
  path: string;
  lineRange?: [number, number];
  note: string;
}

export interface SpecialistStructuredOutput<T = unknown> {
  specialistRole: SpecialistRole;
  status: "SUCCESS" | "FAILED" | "INCONCLUSIVE";
  summary: string;
  findings: T;
  evidence: SpecialistEvidenceItem[];
  escalationRecommended: boolean;
  escalationReason?: string;
}

export function validateSpecialistOutput<T>(
  role: SpecialistRole,
  raw: unknown,
): SpecialistStructuredOutput<T> {
  if (!raw || typeof raw !== "object") {
    throw new Error(`Specialist output must be an object, received: ${typeof raw}`);
  }
  const obj = raw as Record<string, unknown>;
  if (obj.specialistRole !== role) {
    throw new Error(`Specialist output role mismatch: expected '${role}', got '${obj.specialistRole}'`);
  }
  if (!["SUCCESS", "FAILED", "INCONCLUSIVE"].includes(obj.status as string)) {
    throw new Error(`Invalid specialist status: '${obj.status}'`);
  }
  if (typeof obj.summary !== "string" || obj.summary.trim().length === 0) {
    throw new Error("Specialist output must include a non-empty summary string");
  }
  if (!Array.isArray(obj.evidence)) {
    throw new Error("Specialist output must include an evidence array");
  }
  for (const item of obj.evidence) {
    if (!item || typeof item !== "object" || typeof item.path !== "string") {
      throw new Error("Each evidence item must contain a 'path' string");
    }
  }
  return obj as unknown as SpecialistStructuredOutput<T>;
}

/**
 * Deterministic Micro-Routing Engine (Nexus Code v1.1.2)
 *
 * Eliminates unnecessary LLM inference turns for non-semantic, deterministic commands
 * and routes tasks to specialized profiles based on unambiguous rule matching.
 *
 * Principles:
 * 1. Ordinary discovery, test runs, diff inspection, and AST queries remain deterministic.
 * 2. Model-assisted routing is permitted only when rules are ambiguous, and must record
 *    its inputs, confidence, and fallback to deterministic defaults.
 * 3. Model classification can never override hard security or policy constraints.
 */

import { isSpecialistRole, type SpecialistRole } from "./specialist_profiles.js";

export type RoutingKind =
  | "DETERMINISTIC_FASTPATH"
  | "SPECIALIST_DELEGATION"
  | "GENERAL_ENGINEERING";

export interface MicroRoutingDecision {
  kind: RoutingKind;
  ruleId: string;
  targetRole?: SpecialistRole;
  targetTool?: string;
  targetToolArgs?: Record<string, unknown>;
  reason: string;
  confidence: number;
  requiresInference: boolean;
}

interface DeterministicPattern {
  ruleId: string;
  kind: RoutingKind;
  matcher: (input: string) => boolean;
  targetRole?: SpecialistRole;
  targetTool?: string;
  getArgs?: (input: string) => Record<string, unknown>;
  reason: string;
}

const DETERMINISTIC_PATTERNS: DeterministicPattern[] = [
  // 1. Direct test suite execution
  {
    ruleId: "FASTPATH_TEST_RUN",
    kind: "DETERMINISTIC_FASTPATH",
    matcher: (q) => /^(?:run\s+(?:the\s+)?tests?|npm\s+test|cargo\s+test|make\s+test)\s*$/i.test(q.trim()),
    targetTool: "run_tests",
    reason: "Exact request to run project test suite without semantic modification",
  },

  // 2. Exact git diff / status inspection
  {
    ruleId: "FASTPATH_GIT_DIFF",
    kind: "DETERMINISTIC_FASTPATH",
    matcher: (q) => /^(?:git\s+diff|show\s+(?:the\s+)?diff|git\s+status)\s*$/i.test(q.trim()),
    targetTool: "run_command",
    getArgs: (q) => ({ command: q.trim().toLowerCase().startsWith("git") ? q.trim() : "git diff" }),
    reason: "Pure repository diff or status query without code authoring",
  },

  // 3. Security and vulnerability review requests
  {
    ruleId: "SPECIALIST_SECURITY_AUDIT",
    kind: "SPECIALIST_DELEGATION",
    matcher: (q) => /\b(?:security\s+review|vulnerability\s+audit|codeql|dependabot|injection\s+check)\b/i.test(q),
    targetRole: "security_reviewer",
    reason: "Query specifically requests security auditing or vulnerability analysis",
  },

  // 4. Failure investigation & debugging
  {
    ruleId: "SPECIALIST_FAILURE_DEBUG",
    kind: "SPECIALIST_DELEGATION",
    matcher: (q) => /\b(?:investigate\s+(?:the\s+)?failure|diagnose\s+crash|debug\s+test\s+failure|stack\s*trace)\b/i.test(q),
    targetRole: "failure_debugger",
    reason: "Query targets failure triage, diagnostic stack trace analysis, or crash isolation",
  },

  // 5. Dependency & call-site tracing
  {
    ruleId: "SPECIALIST_CALL_SITE",
    kind: "SPECIALIST_DELEGATION",
    matcher: (q) => /\b(?:call\s*sites?|who\s+calls|trace\s+dependencies?|downstream\s+callers?)\b/i.test(q),
    targetRole: "call_site_analyzer",
    reason: "Query targets call graph tracing, dependency flow, or caller discovery",
  },

  // 6. Semantic exploration & search
  {
    ruleId: "SPECIALIST_EXPLORATION",
    kind: "SPECIALIST_DELEGATION",
    matcher: (q) => /\b(?:explore\s+(?:the\s+)?codebase|architecture\s+overview|map\s+the\s+modules?)\b/i.test(q),
    targetRole: "semantic_explorer",
    reason: "Query requests broad architectural reconnaissance or cross-file pattern discovery",
  },

  // 7. Acceptance & review
  {
    ruleId: "SPECIALIST_ACCEPTANCE",
    kind: "SPECIALIST_DELEGATION",
    matcher: (q) => /\b(?:independent\s+review|verify\s+(?:the\s+)?release|acceptance\s+check)\b/i.test(q),
    targetRole: "acceptance_reviewer",
    reason: "Query requests independent validation, acceptance review, or verification gate check",
  },
];

/**
 * Evaluates an input prompt and determines the routing path.
 * Deterministic rules execute with 100% confidence. Unmatched queries fall back to general engineering.
 */
export function routeTaskMicroDecision(input: string): MicroRoutingDecision {
  const normalized = input.trim();

  for (const pattern of DETERMINISTIC_PATTERNS) {
    if (pattern.matcher(normalized)) {
      return {
        kind: pattern.kind,
        ruleId: pattern.ruleId,
        targetRole: pattern.targetRole,
        targetTool: pattern.targetTool,
        targetToolArgs: pattern.getArgs ? pattern.getArgs(normalized) : undefined,
        reason: pattern.reason,
        confidence: 1.0,
        requiresInference: pattern.kind !== "DETERMINISTIC_FASTPATH",
      };
    }
  }

  // Fallback to general engineering execution
  return {
    kind: "GENERAL_ENGINEERING",
    ruleId: "FALLBACK_GENERAL_MODEL",
    reason: "Task requires general code authoring, multi-turn editing, or complex synthesis",
    confidence: 0.85,
    requiresInference: true,
  };
}

