 21 │       );
 22 │     }
 23 │ 
 24 │     if (manifest.evaluationVersion !== baseline.evaluationVersion) {
 25 │       reasons.push(
 26 │         `Evaluation definition version drift: current '${manifest.evaluationVersion}' vs baseline '${baseline.evaluationVersion}'`
 27 │       );
 28 │     }
 29 │ 
 30 │     if (manifest.model.name !== baseline.modelName) {
 31 │       reasons.push(
 32 │         `Model mismatch: current '${manifest.model.name}' vs baseline '${baseline.modelName}'`
 33 │       );
 34 │     }
 35 │ 
 36 │     if (
 37 │       baseline.modelQuantization &&
 38 │       manifest.model.quantization &&
 39 │       manifest.model.quantization !== baseline.modelQuantization
 40 │     ) {
 41 │       reasons.push(
 42 │         `Model quantization mismatch: current '${manifest.model.quantization}' vs baseline '${baseline.modelQuantization}'`
 43 │       );
 44 │     }
 45 │ 
 46 │     if (manifest.dirtyWorktree) {
 47 │       reasons.push("Current run was executed on an uncommitted / dirty worktree");
 48 │     }
 49 │ 
 50 │     return {
 51 │       eligible: reasons.length === 0,
 52 │       reasons,
 53 │     };
 54 │   }
