194 │ export function validateEvaluationDefinition(def: unknown): EvaluationDefinition {
195 │   if (!def || typeof def !== "object") {
196 │     throw new Error("Evaluation definition must be a non-null object");
197 │   }
198 │   const d = def as Partial<EvaluationDefinition>;
199 │   if (!d.id || typeof d.id !== "string") throw new Error("Evaluation definition missing valid 'id'");
200 │   if (!d.version || typeof d.version !== "string") throw new Error("Evaluation definition missing valid 'version'");
201 │   if (!d.domain || typeof d.domain !== "string") throw new Error("Evaluation definition missing valid 'domain'");
202 │   if (!d.objective || typeof d.objective !== "string") throw new Error("Evaluation definition missing valid 'objective'");
203 │   if (!Array.isArray(d.authorizedTools)) throw new Error("Evaluation definition 'authorizedTools' must be an array");
204 │   if (!d.executionBudget || typeof d.executionBudget.maxSteps !== "number" || typeof d.executionBudget.timeoutSeconds !== "number") {
205 │     throw new Error("Evaluation definition missing valid 'executionBudget'");
206 │   }
207 │   if (!Array.isArray(d.deterministicAssertions)) {
208 │     throw new Error("Evaluation definition 'deterministicAssertions' must be an array");
209 │   }
210 │   return d as EvaluationDefinition;
211 │ }
