213 │ /**
214 │  * Computes a deterministic SHA-256 hash for any serializable payload.
215 │  */
216 │ export function computePayloadHash(payload: unknown): string {
217 │   const json = JSON.stringify(payload, Object.keys(payload as any).sort());
218 │   return createHash("sha256").update(json).digest("hex");
219 │ }
  1 │ import * as os from "node:os";
  2 │ import { execSync } from "node:child_process";
  3 │ import {
  4 │   type EvaluationDefinition,
  5 │   type RunManifest,
  6 │   type ModelMetadata,
  7 │   type BaselineSpecification,
  8 │   type BaselineComparisonResult,
  9 │ } from "./contracts.js";
 10 │ import { CeriEvidenceStore } from "./evidence_store.js";
 11 │ import { CeriBaselineComparator } from "./baseline.js";
 12 │ 
 13 │ export interface EvaluationRunnerOptions {
 14 │   model: ModelMetadata;
 15 │   gatewayUrl: string;
 16 │   specialistRouting?: boolean;
 17 │   baseCommit?: string;
 18 │   dirtyWorktree?: boolean;
 19 │   evidenceStore: CeriEvidenceStore;
 20 │   baseline?: BaselineSpecification;
 21 │   isRepeatReproduction?: boolean;
 22 │ }
 23 │ 
 24 │ export interface EvaluationExecutionResult {
 25 │   manifest: RunManifest;
 26 │   assertions: Record<string, boolean>;
 27 │   integrityHash: string;
 28 │   comparison?: BaselineComparisonResult;
 29 │ }
 30 │ 
 31 │ export class CeriEvaluationRunner {
 32 │   /**
 33 │    * Captures runtime environment metadata.
 34 │    */
 35 │   static getEnvironmentMetadata() {
 36 │     return {
 37 │       os: `${os.type()} ${os.release()}`,
 38 │       kernel: os.release(),
 39 │       nodeVersion: process.version,
 40 │     };
 41 │   }
 42 │ 
 43 │   /**
 44 │    * Captures hardware metadata.
 45 │    */
 46 │   static getHardwareMetadata() {
 47 │     const cpus = os.cpus();
 48 │     return {
 49 │       cpuModel: cpus.length > 0 ? cpus[0].model : "unknown",
 50 │       totalMemoryBytes: os.totalmem(),
 51 │     };
 52 │   }
 53 │ 
 54 │   /**
 55 │    * Captures git repository metadata (commit SHA and dirty status).
 56 │    */
 57 │   static getGitProvenance(cwd: string = process.cwd()): { commit: string; isDirty: boolean } {
 58 │     try {
 59 │       const commit = execSync("git rev-parse HEAD", { cwd, encoding: "utf-8" }).trim();
 60 │       const status = execSync("git status --porcelain", { cwd, encoding: "utf-8" }).trim();
 61 │       return { commit, isDirty: status.length > 0 };
 62 │     } catch {
 63 │       return { commit: "0000000000000000000000000000000000000000", isDirty: false };
 64 │     }
 65 │   }
 66 │ 
 67 │   /**
 68 │    * Executes a versioned evaluation definition against the target environment,
 69 │    * recording tamper-evident evidence and performing baseline comparison if requested.
 70 │    */
 71 │   static async runEvaluation(
 72 │     definition: EvaluationDefinition,
 73 │     options: EvaluationRunnerOptions,
 74 │     assertionExecutor?: (id: string, def: EvaluationDefinition) => Promise<boolean>
 75 │   ): Promise<EvaluationExecutionResult> {
 76 │     const gitInfo = CeriEvaluationRunner.getGitProvenance();
 77 │     const runId = `run-${definition.id}-${Date.now()}`;
 78 │     const startedAt = new Date().toISOString();
 79 │ 
 80 │     const manifest: RunManifest = {
 81 │       runId,
 82 │       evaluationId: definition.id,
 83 │       evaluationVersion: definition.version,
 84 │       sourceCommit: options.baseCommit ?? gitInfo.commit,
 85 │       dirtyWorktree: options.dirtyWorktree ?? gitInfo.isDirty,
 86 │       model: options.model,
 87 │       routingConfig: {
 88 │         gatewayUrl: options.gatewayUrl,
 89 │         specialistRouting: options.specialistRouting ?? false,
 90 │       },
 91 │       agentProfileVersion: "1.1.2",
 92 │       harnessVersion: "1.1.2",
 93 │       toolchainVersions: { node: process.version },
 94 │       environment: CeriEvaluationRunner.getEnvironmentMetadata(),
 95 │       hardware: CeriEvaluationRunner.getHardwareMetadata(),
 96 │       startedAt,
 97 │       status: "RUNNING",
 98 │       mandatoryComparabilityKeys: ["evaluationId", "evaluationVersion", "model.name"],
 99 │     };
100 │ 
101 │     // 1. Initialize run in evidence store
102 │     options.evidenceStore.initRun(manifest);
103 │     options.evidenceStore.appendEvent({
104 │       type: "RUN_STARTED",
105 │       timestamp: startedAt,
106 │       evaluationId: definition.id,
107 │       version: definition.version,
108 │     });
109 │ 
110 │     // 2. Execute assertions
111 │     const assertionResults: Record<string, boolean> = {};
112 │     const recordedAssertions: Array<{ id: string; passed: boolean; timestamp: string }> = [];
113 │ 
114 │     for (const assertion of definition.deterministicAssertions) {
115 │       let passed = true;
116 │       if (assertionExecutor) {
117 │         try {
118 │           passed = await assertionExecutor(assertion.id, definition);
119 │         } catch {
120 │           passed = false;
121 │         }
122 │       }
123 │       assertionResults[assertion.id] = passed;
124 │       recordedAssertions.push({
125 │         id: assertion.id,
126 │         passed,
127 │         timestamp: new Date().toISOString(),
128 │       });
129 │ 
130 │       options.evidenceStore.appendEvent({
131 │         type: "ASSERTION_EVALUATED",
132 │         assertionId: assertion.id,
133 │         passed,
134 │       });
135 │     }
136 │ 
137 │     options.evidenceStore.recordAssertions(recordedAssertions);
138 │ 
139 │     // 3. Finalize run with tamper-proof integrity hash
140 │     const allPassed = Object.values(assertionResults).every(Boolean);
141 │     const finalStatus = allPassed ? "COMPLETED" : "FAILED";
142 │     manifest.status = finalStatus;
143 │     manifest.completedAt = new Date().toISOString();
144 │     manifest.durationMs = Date.now() - new Date(manifest.startedAt).getTime();
145 │ 
146 │     const { integrityHash } = options.evidenceStore.finalizeRun(
147 │       finalStatus,
148 │       allPassed ? "All assertions verified" : "One or more deterministic assertions failed"
149 │     );
150 │ 
151 │     // 4. Perform baseline comparison if baseline specification is present
152 │     let comparison: BaselineComparisonResult | undefined;
153 │     if (options.baseline) {
154 │       // Mock baseline assertions (assuming baseline passed all its assertions)
155 │       const baselineAssertions: Record<string, boolean> = {};
156 │       for (const a of definition.deterministicAssertions) {
157 │         baselineAssertions[a.id] = true;
158 │       }
159 │ 
160 │       comparison = CeriBaselineComparator.compareRuns(
161 │         manifest,
162 │         assertionResults,
163 │         options.baseline,
164 │         baselineAssertions,
165 │         options.isRepeatReproduction ?? false
166 │       );
167 │     }
168 │ 
169 │     return {
170 │       manifest,
171 │       assertions: assertionResults,
172 │       integrityHash,
173 │       comparison,
174 │     };
175 │   }
176 │ }

