20 │ export class CeriInvestigationCoordinator {
21 │   /**
22 │    * Validates that an investigation finding adheres to epistemological discipline:
23 │    * Any INFERENCE or CONFIRMED_FINDING must cite at least one explicit evidence reference.
24 │    */
25 │   static validateFinding(finding: InvestigationFinding): void {
26 │     if (!finding.id || typeof finding.id !== "string") {
27 │       throw new InvestigationValidationError("Finding missing valid 'id'");
28 │     }
29 │     if (!finding.type || typeof finding.type !== "string") {
30 │       throw new InvestigationValidationError("Finding missing valid 'type'");
31 │     }
32 │     if (!finding.description || typeof finding.description !== "string") {
33 │       throw new InvestigationValidationError("Finding missing valid 'description'");
34 │     }
35 │ 
36 │     if (
37 │       (finding.type === "INFERENCE" || finding.type === "CONFIRMED_FINDING") &&
38 │       (!Array.isArray(finding.evidenceReferences) || finding.evidenceReferences.length === 0)
39 │     ) {
40 │       throw new InvestigationValidationError(
41 │         `Finding '${finding.id}' of type '${finding.type}' must cite at least one valid evidence reference`
42 │       );
43 │     }
44 │   }
45 │ 
46 │   /**
47 │    * Constructs a structured investigation report, verifying that findings
48 │    * maintain a clear boundary between observation, hypothesis, and confirmed reality.
49 │    */
50 │   static createReport(params: {
51 │     investigationId: string;
52 │     targetRunId: string;
53 │     baselineId: string;
54 │     findings: InvestigationFinding[];
55 │     summary: string;
56 │   }): InvestigationReport {
57 │     // Validate each finding
58 │     for (const f of params.findings) {
59 │       this.validateFinding(f);
60 │     }
61 │ 
62 │     const hasUnresolvedUncertainty = params.findings.some(
63 │       (f) => f.type === "UNRESOLVED_UNCERTAINTY"
64 │     );
65 │ 
66 │     return {
67 │       investigationId: params.investigationId,
68 │       targetRunId: params.targetRunId,
69 │       baselineId: params.baselineId,
70 │       findings: [...params.findings],
71 │       summary: params.summary,
72 │       hasUnresolvedUncertainty,
73 │       createdAt: new Date().toISOString(),
74 │     };
75 │   }
76 │ }
