  log("P8c baseline that also failed a1 -> outcome (runner mocks baseline as all-pass)", r2.comparison?.outcome);
  // P9 new failing assertion vs baseline
  const m: any = { ...r2.manifest, status: "COMPLETED" };
  log("P9 new assertion passing absent from baseline", CeriBaselineComparator.compareRuns(m, { a1: true, newA: true }, spec, { a1: true }).outcome);
