  log("P10 report banner for 1 FAILED+INCOMPARABLE run", CeriReportGenerator.formatMarkdownReport(rep).split("\n").find(l => l.includes("**NO") || l.includes("BLOCK") || l.includes("QUALIF")));
  // P11 self approval bypass / re-review
  const p = RemediationProposalManager.createProposal({ id: "p", targetIssue: "i", authorAgent: "agent-a", reproductionSteps: [], proposedDiff: "", testRecommendations: [] });
  log("P11 self-approve as 'Agent-A '", RemediationProposalManager.reviewProposal(p, "Agent-A ", "APPROVED", "x").approvalStatus);
  const rej = RemediationProposalManager.reviewProposal(p, "rev", "REJECTED", "no");
  log("P11b re-review rejected proposal by another id", RemediationProposalManager.reviewProposal(rej, "rev2", "APPROVED", "y").approvalStatus);
});
