285	export interface ObservationVerdict {
286	  key: string;
287	  record: RepetitionRecord;
288	  /** The triple was seen before (on a known state): no new information. */
289	  repeat: boolean;
290	  /** New information from an observing action. */
291	  informative: boolean;
292	  /** Third (or later) recurrence of a deterministic action/outcome on a known unchanged state. */
293	  loop: boolean;
294	  /** Recurrence of an external action's unchanged result, or of a transient failure: waits, not a loop. */
295	  poll: boolean;
296	  stateUnknown: boolean;
297	  /** Re-acquisition of output compaction removed (never a loop); `thrash` once it has recurred REPEAT_THRESHOLD - 1 times. */
298	  reacquired: boolean;
299	  thrash: boolean;
300	}
