492	/** Digest of what the acceptance ledger asserts (statuses and evidence), excluding the plan and the next-action note. */
493	export function ledgerStateIdentity(requirements: Array<{ id: string; status: string; evidence: string[] }>, verification?: { status?: string; candidateId?: string } | null): string {
494	  return digest(JSON.stringify([requirements.map((r) => [r.id, r.status, [...r.evidence].sort()]), verification?.status ?? null, verification?.candidateId ?? null]));
