497	/** Digest combining the parts of a state identity; any unknown part makes the whole unknown. */
498	export function combineState(parts: Array<string | undefined>): string {
499	  if (parts.some((p) => p === undefined || p === "unknown")) return "unknown";
500	  return digest(parts.join("\u0000"));
501	}
