3	/**
4	 * Objective-scoped execution tracking: how many steps the work has taken (observability only, never a termination
5	 * condition), what counted as progress, which actions recurred without it, what failed, and what Nexus did about it.
6	 * It lives in the objective ledger, so compaction (which rewrites the conversation only), follow-up turns on the same
7	 * objective (which amend the ledger) and restart (which restores the ledger) all keep it. A new objective starts a new
8	 * ledger and so new tracking; `/requirements clear` and `/clear` reset it explicitly.
9	 *
10	 * Progress is judged from three identities, never from tool-call equality alone:
11	 * - action identity: tool name and canonical arguments (key order, whitespace and call ids do not matter);
12	 * - outcome identity: success and the output with volatile tokens (timestamps, durations, uuids, addresses, request
13	 *   ids, temporary paths) normalized away, so a changed clock in the output is not new information;
14	 * - state identity: the workspace's content identity (candidate identity: HEAD plus content of changed and untracked
15	 *   files), the git index, the content of dependency/environment inputs git ignores, and the PATH. Content, not
16	 *   mtimes: rewriting a file with identical content changes nothing. When it cannot be established it is "unknown"
17	 *   and every judgement that depends on it says so instead of asserting the state is unchanged.
18	 *
19	 * A step progressed when it reached a workspace state not seen before on this objective, observed something new (an
20	 * action/outcome/state triple not seen before, from an action that observes rather than mutates), changed the
21	 * acceptance ledger to a state not seen before, or applied operator input. Plan edits, re-formatted arguments, new
22	 * tool-call ids, re-writing identical content and returning to an earlier state are not progress.
23	 *
24	 * Storage is bounded. Repetition records that show a recurrence (count >= 2) are never evicted for a single-count
25	 * record; seen-sets are kept as 16-hex digests (MAX_SEEN each), oldest first out, with the number evicted recorded.
26	 * A loop must recur on the same triple, so it is caught by its repetition record however long the objective runs.
27	 */
28	
29	export const TRACKING_VERSION = 1;
30	
31	/** The third identical action/outcome on an unchanged state is a demonstrated loop (two can be a legitimate re-check). */
32	export const REPEAT_THRESHOLD = 3;
33	const MAX_REPETITIONS = 256;
34	const MAX_SEEN = 4096;
35	const MAX_EVENTS = 64;
36	const MAX_FAILED = 64;
37	const MAX_INTERVENTIONS = 128;
38	const MAX_COMPACTIONS = 128;
39	
40	/** Backoff before re-running an unchanged poll or a transient failure: doubles from 1 s, capped at 30 s. */
41	export const BACKOFF_BASE_MS = 1_000;
42	export const BACKOFF_MAX_MS = 30_000;
43	
44	export type OutcomeClass = "success" | "transient_failure" | "deterministic_failure";
45	/**
46	 * How an action relates to state. `observe_workspace`: its result is determined by the workspace state (reading files),
47	 * so repeating it on an unchanged state cannot yield anything new. `external`: its result may depend on state outside
48	 * the workspace (commands, network), so an unchanged repeat is a poll. `mutate`: it changes the workspace; its progress
49	 * is the state it reaches. `bookkeeping`: plan notes and similar, never progress.
50	 */
51	export type ActionKind = "observe_workspace" | "external" | "mutate" | "bookkeeping";
52	
53	export interface RepetitionRecord {
54	  /** Digest of action, outcome and input state. */
55	  key: string;
56	  /** Readable action: tool and subject, clipped. */
57	  action: string;
58	  /** Digest of the action identity alone (tool and canonical arguments). */
59	  actionId: string;
60	  actionKind: ActionKind;
61	  outcomeClass: OutcomeClass;
62	  /** Input state identity, or "unknown". */
63	  state: string;
64	  count: number;
65	  /**
66	   * Occurrences that re-acquired output compaction had removed from the model's context: not repetition (the model
67	   * no longer had the result), but evidence of context thrash when it recurs.
68	   */
69	  reacquired?: number;
70	  firstStep: number;
71	  lastStep: number;
72	  /** Clipped normalized outcome, kept as evidence. */
73	  outcome: string;
74	}
75	
76	export interface TrackingEvent {
77	  step: number;
78	  at: string;
79	  kind: string;
80	  detail: string;
81	}
