97	export interface ExecutionTracking {
98	  version: number;
99	  /** Steps run against this objective across all turns (observability; no limit is derived from it). */
100	  cumulativeSteps: number;
101	  turns: number;
102	  /** Consecutive steps without progress, across turns; operator input resets it. */
103	  stepsWithoutProgress: number;
104	  lastProgressStep: number;
105	  repetitions: RepetitionRecord[];
106	  progress: TrackingEvent[];
107	  stagnation: TrackingEvent[];
108	  failedApproaches: TrackingEvent[];
109	  interventions: TrackingEvent[];
110	  compactions: CompactionEvent[];
111	  /** Consecutive pressure compactions that yielded little (thrashing evidence; reset by a useful one). */
112	  lowYieldCompactions: number;
113	  seenStates: string[];
114	  seenObservations: string[];
115	  seenLedgerStates: string[];
116	  evicted: { states: number; observations: number; ledgerStates: number; repetitions: number; events: number };
117	}
