      for (const cmd of unsupported) assert.ok(ran.some((r) => JSON.parse(r.args).command === cmd), `${cmd} ran`);
      assert.ok(gw.requests.length <= 14, `bounded by the stagnation window: ${gw.requests.length}`);
    } finally {
