/**
 * Baseline-vs-candidate replay of NONPROGRESS-20261101-DOCTOR. Uses only interfaces present on both trees (runTurn's
 * result, the conversation, dispatchToolCall), so the same file runs unchanged on origin/main and on the candidate.
 * Prints one JSON line per scenario: PROBE_RESULT {...}.
 */
import { test } from "node:test";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { AutonomousAgent } from "../src/agent.js";
import { DEFAULT_CONTINUATION } from "../src/types.js";
import { startGateway, makeRepo } from "./helpers/fixtures.js";

const fixture = JSON.parse(fs.readFileSync(process.env.NP_FIXTURE!, "utf8"));
const lines = (prefix: string, n: number) => Array.from({ length: n }, (_, i) => `${prefix} line ${i + 1}`).join("\n") + "\n";
const quiet = (a: AutonomousAgent) => ((a as any).ui = new Proxy({}, { get: () => () => {} }), a);

async function run(name: string, script: (n: number, body: any) => any, files: Record<string, string>, prompt: string) {
  const home = fs.mkdtempSync(path.join(os.tmpdir(), "np-cmp-home-"));
  process.env.HOME = home;
  const repo = makeRepo(files);
  const gw = await startGateway(script);
  const agent = quiet(new AutonomousAgent({ endpoint: gw.url, model: "m", maxSteps: 30, temperature: 0, workspace: repo, shell: "bash", approvalMode: "auto", fullAccess: true, continuation: { ...DEFAULT_CONTINUATION, stagnationSteps: 30, maxRecoveries: 2 } } as any));
  const ran: Array<{ name: string; args: string }> = [];
  const orig = (agent as any).dispatchToolCall.bind(agent);
  (agent as any).dispatchToolCall = async (call: any, ...rest: unknown[]) => {
    ran.push({ name: call.function.name, args: typeof call.function.arguments === "string" ? call.function.arguments : JSON.stringify(call.function.arguments) });
    return orig(call, ...rest);
  };
  const started = Date.now();
  try {
    const turn = await agent.runTurn(prompt);
    const msgs = agent.getMessages() as any[];
    const notes = gw.requests.map((b: any) => ((b.messages ?? []) as any[]).filter((m) => m.role === "user" && /^\[Nexus recovery/.test(String(m.content))).length);
    // Requests the model answered after each recovery note first appeared.
    const firstNoteAt = (re: RegExp) => gw.requests.findIndex((b: any) => ((b.messages ?? []) as any[]).some((m) => m.role === "user" && re.test(String(m.content))));
    const n1 = firstNoteAt(/^\[Nexus recovery 1\//);
    const n2 = firstNoteAt(/^\[Nexus recovery 2\//);
    const readKey = (r: { name: string; args: string }) => (r.name === "read_file" ? JSON.parse(r.args).path : r.name === "run_command" ? JSON.parse(r.args).command : r.name);
    const executedReads = ran.filter((r) => r.name === "read_file");
    const distinct = new Set(executedReads.map((r) => r.args));
    console.log("PROBE_RESULT " + JSON.stringify({
      scenario: name,
      execution: turn.execution,
      reason: turn.reason,
      detail: turn.detail,
      requests: gw.requests.length,
      executedToolCalls: ran.length,
      executedReads: executedReads.length,
      duplicateReadExecutions: executedReads.length - distinct.size,
      refusedCalls: msgs.filter((m) => m.role === "tool" && String(m.content).startsWith("[Nexus refused: not executed]")).length,
      notesDelivered: { first: n1, second: n2, requestsAfterSecondNote: n2 >= 0 ? gw.requests.length - n2 : 0 },
      tokens: (agent as any).totalTokens?.total ?? null,
      ms: Date.now() - started,
      lastExecuted: ran.slice(-3).map(readKey),
    }));
    void notes;
  } finally {
    agent.shutdown();
    await gw.close();
    fs.rmSync(repo, { recursive: true, force: true });
    fs.rmSync(home, { recursive: true, force: true });
  }
}

test("incident replay", { timeout: 300_000 }, async () => {
  const files = Object.fromEntries(Object.entries(fixture.files as Record<string, { lines: number; prefix: string }>).map(([p, f]) => [p, lines(f.prefix, f.lines)]));
  const prelude = fixture.prelude as Array<{ content: string; calls: any[] }>;
  await run("incident", (n) => {
    if (n <= prelude.length) return { kind: "tools", calls: prelude[n - 1].calls, content: prelude[n - 1].content };
    const i = n - prelude.length - 1;
    return { kind: "tools", calls: fixture.repeat.calls, content: fixture.repeat.contents[i % fixture.repeat.contents.length] };
  }, files, "Find and fix a real bug in the doctor command, with a regression test.");
});

test("incident replay with a model that follows the constrained note", { timeout: 300_000 }, async () => {
  const files = Object.fromEntries(Object.entries(fixture.files as Record<string, { lines: number; prefix: string }>).map(([p, f]) => [p, lines(f.prefix, f.lines)]));
  const prelude = fixture.prelude as Array<{ content: string; calls: any[] }>;
  // A model that changes approach only once it is told what it already has (RECOVERY_REQUIRED) or is refused.
  await run("incident-responsive", (n, body) => {
    const all = ((body?.messages ?? []) as any[]).map((m) => String(m.content)).join("\n");
    if (/fix\.patch/.test(all)) return { kind: "text", content: "Wrote the regression test from the evidence already gathered." };
    if (/RECOVERY_REQUIRED|\[Nexus refused: not executed\]/.test(all)) return { kind: "tools", calls: [{ name: "write_file", args: { path: "cli/test/fix.patch", content: "test\n" } }] };
    if (n <= prelude.length) return { kind: "tools", calls: prelude[n - 1].calls, content: prelude[n - 1].content };
    const i = n - prelude.length - 1;
    return { kind: "tools", calls: fixture.repeat.calls, content: fixture.repeat.contents[i % fixture.repeat.contents.length] };
  }, files, "Find and fix a real bug in the doctor command, with a regression test.");
});

test("cross-interface re-reads", { timeout: 300_000 }, async () => {
  const forms = [
    { name: "read_file", args: { path: "f.txt" } },
    { name: "run_command", args: { command: "cat f.txt" } },
    { name: "run_command", args: { command: "sed -n '1,20p' f.txt" } },
    { name: "run_command", args: { command: "head -n 5 f.txt" } },
  ];
  await run("cross-interface", (n) => (n <= 12 ? { kind: "tools", calls: [forms[(n - 1) % forms.length]] } : { kind: "text", content: "done" }), { "f.txt": lines("f", 30) }, "Look at f.txt.");
});

test("read-only investigation (false-positive check)", { timeout: 300_000 }, async () => {
  const script = [[{ name: "read_file", args: { path: "a.txt" } }], [{ name: "read_file", args: { path: "b.txt" } }, { name: "read_file", args: { path: "c.txt" } }], [{ name: "read_file", args: { path: "a.txt", start_line: 2, end_line: 4 } }]];
  await run("read-only", (n) => (n <= script.length ? { kind: "tools", calls: script[n - 1] } : { kind: "text", content: "five lines each" }), { "a.txt": lines("a", 5), "b.txt": lines("b", 5), "c.txt": lines("c", 5) }, "Count lines; change nothing.");
});

