    if (n <= prelude.length) return { kind: "tools", calls: prelude[n - 1].calls, content: prelude[n - 1].content };
    const i = n - prelude.length - 1;
    return { kind: "tools", calls: fixture.repeat.calls, content: fixture.repeat.contents[i % fixture.repeat.contents.length] };
  }, files, "Find and fix a real bug in the doctor command, with a regression test.");
});

test("cross-interface re-reads", { timeout: 300_000 }, async () => {
  const forms = [
    { name: "read_file", args: { path: "f.txt" } },
    { name: "run_command", args: { command: "cat f.txt" } },
    { name: "run_command", args: { command: "sed -n '1,20p' f.txt" } },
    { name: "run_command", args: { command: "head -n 5 f.txt" } },
  ];
  await run("cross-interface", (n) => (n <= 12 ? { kind: "tools", calls: [forms[(n - 1) % forms.length]] } : { kind: "text", content: "done" }), { "f.txt": lines("f", 30) }, "Look at f.txt.");
});

