  const script = [[{ name: "read_file", args: { path: "a.txt" } }], [{ name: "read_file", args: { path: "b.txt" } }, { name: "read_file", args: { path: "c.txt" } }], [{ name: "read_file", args: { path: "a.txt", start_line: 2, end_line: 4 } }]];
  await run("read-only", (n) => (n <= script.length ? { kind: "tools", calls: script[n - 1] } : { kind: "text", content: "five lines each" }), { "a.txt": lines("a", 5), "b.txt": lines("b", 5), "c.txt": lines("c", 5) }, "Count lines; change nothing.");
});

