recordDenial(step: number, denial: RecoveryDenial): boolean {
  const r = this.data.recovery;
  r.denials++;
  this.recoveryEvent(step, "tool_execution_denied", `${denial.action}: not executed; ${denial.reason} (${r.denials}/${r.allowedDenials})`);
