import { test } from "node:test";
import fs from "node:fs";
import { AutonomousAgent } from "../src/agent.js";
import { DEFAULT_CONTINUATION } from "../src/types.js";
import { startGateway, makeRepo } from "./helpers/fixtures.js";
const lines = (p: string, n: number) => Array.from({ length: n }, (_, i) => `${p} line ${i + 1}`).join("\n") + "\n";
const quiet = (a: any) => ((a.ui = new Proxy({}, { get: () => () => {} })), a);
const read = (p: string, s?: number, e?: number) => ({ name: "read_file", args: { path: p, ...(s ? { start_line: s } : {}), ...(e ? { end_line: e } : {}) } });
const sh = (command: string) => ({ name: "run_command", args: { command } });
test("cross", { timeout: 120000 }, async () => {
  const repo = makeRepo({ "f.txt": lines("f", 30) });
  const script = [[read("f.txt")], [sh("cat f.txt")], [sh("sed -n '1,20p' f.txt")], [sh("head -n 5 f.txt")], [sh("cat ./f.txt")], [read("f.txt", 3, 9)], [sh(`cd ${repo} && head -3 f.txt`)]];
  const gw = await startGateway((n) => (n <= script.length ? { kind: "tools", calls: script[n - 1] } : { kind: "text", content: "end" }));
  const agent = quiet(new AutonomousAgent({ endpoint: gw.url, model: "m", maxSteps: 30, temperature: 0, workspace: repo, shell: "bash", approvalMode: "auto", fullAccess: true, continuation: { ...DEFAULT_CONTINUATION, stagnationSteps: 30, maxRecoveries: 2 } } as any));
  try {
    const t = await agent.runTurn("x");
    const ex = agent.getObjective()!.execution! as any;
    console.log("DBG", t.reason, t.detail, "requests", gw.requests.length);
    for (const e of ex.recovery.events) console.log("DBG ev", e.step, e.kind, e.detail.slice(0, 220));
    for (const m of agent.getMessages() as any[]) if (m.role === "tool") console.log("DBG tool", String(m.content).slice(0, 220).replace(/\n/g, "\\n"));
  } finally { agent.shutdown(); await gw.close(); fs.rmSync(repo, { recursive: true, force: true }); }
});
EOF
